import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';

const messages = defineMessages({
  positionLabel: {
    id: 'slide_indicator.position.label',
    defaultMessage: 'Image {current} of {total}',
  },
});

const ZIMM_SLIDE_INDICATOR_RECIPE = 'ZimmSlideIndicator';

type ZimmSlideIndicatorProps = {
  /** Total number of images/slides the strip represents. */
  count: number;
  /** Index (0-based) of the currently active/visible slide. Out-of-range values are clamped. */
  activeIndex: number;
};

/**
 * Molecule — read-only image-position indicator for touch devices (tablet + mobile) on the
 * PDP/card image strip. Figma node 40002536:7957 ("Slide indicator"): a segmented 1px hairline
 * strip, one segment per image, the active segment picked out by colour. NOT floating dots.
 *
 * Touch-only per the resolved arrows-vs-indicator split (SFCC-236 plan §4a): hover-capable
 * pointers get prev/next arrow buttons instead (a separate component) and never render this
 * molecule. Because no arrows exist wherever this DOES render, it is the *sole* position signal
 * available there — the root is exposed (`role="group"` + a computed `aria-label`), never
 * `aria-hidden`, while the individual segments are purely decorative (`aria-hidden`) so
 * assistive tech announces the position once via the group label, not once per segment.
 *
 * Renders nothing for `count <= 1` — a single image has no position to indicate among.
 */
export const ZimmSlideIndicator = ({ count, activeIndex }: ZimmSlideIndicatorProps) => {
  const intl = useIntl();

  // Out-of-range clamps rather than throwing: activeIndex < 0 treats as the first slide,
  // activeIndex >= count treats as the last. Written explicitly rather than relying on
  // Array.map/index lookups to silently no-op on an out-of-range value.
  const clampedIndex = Math.min(Math.max(activeIndex, 0), count - 1);

  // Two static resolutions (isActive: false / true), not one per rendered segment — calling
  // useMultiStyleConfig inside the render loop below would be a conditional/looped hook call.
  // Which of the two resolved objects applies to a given segment is picked per-element in the
  // map below instead.
  const styles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: false });
  const activeStyles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: true });

  // A single image has nothing to indicate a position among.
  if (count <= 1) return null;

  const label = intl.formatMessage(messages.positionLabel, {
    current: clampedIndex + 1,
    total: count,
  });

  return (
    <chakra.div role="group" aria-label={label} __css={styles.root}>
      {Array.from({ length: count }, (_, i) => {
        const isActive = i === clampedIndex;
        return (
          <chakra.div
            key={i}
            aria-hidden
            data-active={isActive ? 'true' : undefined}
            __css={isActive ? activeStyles.dot : styles.dot}
          />
        );
      })}
    </chakra.div>
  );
};

export default ZimmSlideIndicator;

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the touch-only PDP/card image position indicator — a 1px hairline strip, one
 * segment per image, the current position picked out by colour. Figma node 40002536:7957
 * ("Slide indicator") confirms only the strip's height (1px, flush to the image's bottom edge)
 * and that it is NOT floating dots; per-segment width/gap and the exact colour pairing are not
 * broken out in the export handed to this step, so both are treated as open design decisions
 * (documented below) rather than invented pixel-for-pixel guesses — same precedent as
 * zimmColourSwatchGroup's `pagination` part leaving an unconfirmed inter-button gap at the flex
 * default rather than inventing one.
 *
 * Two parts:
 *   - `root` — the full-width flex strip, exactly `--zimm-scale-025` (1px) tall.
 *   - `dot` — one equal-width segment per image (despite the part name, this renders as a
 *     rectangle in a hairline, not a circular dot — the name matches this component's
 *     already-agreed contract, not a literal shape description).
 */
export const ZimmSlideIndicator = {
  parts: ['root', 'dot'],

  baseStyle: ({ isActive }: { isActive?: boolean }): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      // Fluid, not a fixed Figma px width — matches the product card's own "fluid, not 288px"
      // rule (SFCC-236 plan §4): this strip always spans whatever width its image parent gives
      // it, rather than the specific 159.11px/99.44px bounding boxes the two sampled Figma
      // variants happened to measure at their own artboard widths.
      width: '100%',
      height: 'var(--zimm-scale-025)', // 1px — the one dimension Figma confirms directly.
      // No confirmed inter-segment gap value in the export handed to this step — left at 0
      // (segments flush-adjacent) rather than invented, so the strip reads as one continuous
      // hairline with the active segment picked out by colour alone. Revisit if a designer
      // confirms a real gap value.
      gap: 0,
    },

    dot: {
      // Equal-width segments filling the strip — no confirmed per-segment width ratio exists
      // to justify an unequal split (see root's own comment above).
      flex: '1 0 0',
      height: '100%',
      // Both colours derive from the same grey/900 primitive (see foundation/colour.ts's
      // `opacity` family), so "active" and "inactive" read as solid vs. dimmed versions of one
      // hairline colour rather than two unrelated tones — a reasonable placeholder pairing
      // pending UI-designer confirmation of the exact treatment (only the strip's geometry, not
      // its colour, is confirmed by the Figma export handed to this step).
      background: isActive ? 'var(--zimm-color-text-default)' : 'var(--zimm-color-opacity-40)',
    },
  }),
};

import type { Meta, StoryObj } from '@storybook/react';
import React from 'react';
import { ZimmSlideIndicator } from './index';

const meta: Meta<typeof ZimmSlideIndicator> = {
  title: 'Elements/ZimmSlideIndicator',
  component: ZimmSlideIndicator,
  parameters: { layout: 'padded' },
};

export default meta;
type Story = StoryObj<typeof ZimmSlideIndicator>;

/** Figma 40002536:7957 — touch-only position indicator, 5 images, first slide active. */
export const Default: Story = {
  args: {
    count: 5,
    activeIndex: 0,
  },
};

/** `Qty images = 5` Figma variant set, a middle slide active. */
export const FiveImages: Story = {
  args: {
    count: 5,
    activeIndex: 2,
  },
};

/** `Qty images = 8` Figma variant set, a middle slide active. */
export const EightImages: Story = {
  args: {
    count: 8,
    activeIndex: 3,
  },
};

/** First slide selected. */
export const FirstSelected: Story = {
  args: {
    count: 5,
    activeIndex: 0,
  },
};

/** Last slide selected. */
export const LastSelected: Story = {
  args: {
    count: 5,
    activeIndex: 4,
  },
};

import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmSlideIndicator } from './index';

// The recipe's actual colour/geometry values aren't relevant to this component's own contract
// (segment count, which one is active, accessibility) — mock the same flat-parts shape the
// zimmColourSwatchGroup test uses so no real Chakra theme is needed.
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({ root: {}, dot: {} }),
  };
});

const wrap = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en" defaultLocale="en">
      {ui}
    </IntlProvider>,
  );

const segments = (container: HTMLElement) => Array.from(container.querySelectorAll('[aria-hidden="true"]'));
const activeSegments = (container: HTMLElement) => container.querySelectorAll('[data-active="true"]');

describe('ZimmSlideIndicator — segment count', () => {
  test('renders exactly 5 segments for count=5', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={0} />);
    expect(segments(container)).toHaveLength(5);
  });

  test('renders exactly 8 segments for count=8', () => {
    const { container } = wrap(<ZimmSlideIndicator count={8} activeIndex={0} />);
    expect(segments(container)).toHaveLength(8);
  });
});

describe('ZimmSlideIndicator — exactly one active segment', () => {
  test('marks the first segment active when activeIndex=0', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={0} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(0);
  });

  test('marks the middle segment active', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={2} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(2);
  });

  test('marks the last segment active when activeIndex=count-1', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={4} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(4);
  });
});

describe('ZimmSlideIndicator — out-of-range activeIndex clamps rather than throwing', () => {
  test('activeIndex=-1 clamps to the first segment', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={-1} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(0);
  });

  test('activeIndex=count (one past the end) clamps to the last segment', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={5} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(4);
  });
});

describe('ZimmSlideIndicator — count <= 1 renders nothing', () => {
  test('count=0 renders nothing', () => {
    const { container } = wrap(<ZimmSlideIndicator count={0} activeIndex={0} />);
    expect(container.firstChild).toBeNull();
  });

  test('count=1 renders nothing', () => {
    const { container } = wrap(<ZimmSlideIndicator count={1} activeIndex={0} />);
    expect(container.firstChild).toBeNull();
  });
});

describe('ZimmSlideIndicator — accessibility (sole position signal on touch, see plan §4a)', () => {
  test('the root group is not aria-hidden', () => {
    wrap(<ZimmSlideIndicator count={5} activeIndex={1} />);
    const root = screen.getByRole('group');
    expect(root).not.toHaveAttribute('aria-hidden', 'true');
  });

  test('the root exposes the current position as its accessible name', () => {
    wrap(<ZimmSlideIndicator count={5} activeIndex={1} />);
    expect(screen.getByRole('group', { name: 'Image 2 of 5' })).toBeInTheDocument();
  });

  test('the accessible name reflects a clamped out-of-range activeIndex', () => {
    wrap(<ZimmSlideIndicator count={5} activeIndex={-1} />);
    expect(screen.getByRole('group', { name: 'Image 1 of 5' })).toBeInTheDocument();
  });
});

